from collections import defaultdict

def isCircle(N, A):
    degree = defaultdict(int)
    graph = defaultdict(list)

    for s in A:
        start, end = s[0], s[-1]
        graph[start].append(end)
        degree[start] += 1
        degree[end] -= 1

    odd_count = sum(1 for count in degree.values() if count % 2 != 0)

    if odd_count != 0:
        return 0

    visited = set()

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)
            for neighbor in graph[current]:
                stack.append(neighbor)

    dfs(A[0][0])

    if len(visited) != len(graph):
        return 0

    return 1
